from taf.fdsw.rc.interfaces.exceptions import OperationFailure
from taf.fdsw.rc.interfaces.FDSW19A.autoconnection import AutoConfiguration19A
from taf.fdsw.rc.schemas.FDSW20B.autoconnection_parameters_builder_20b import \
    AutoconnectionParametersBuilder20B


class AutoConfiguration20B(AutoConfiguration19A):
    param_builder = AutoconnectionParametersBuilder20B

    def __init__(self, client):
        super(AutoConfiguration20B, self).__init__(client)

    def autoconnection_parameters(self, timeout=10):
        autoconnection = self._client.send(
            method='config.autoconnection.fetch',
            timeout=timeout,
            parameters={})
        return autoconnection

    def set_site_identification(self, autoconnection_site_id, timeout=10):
        super(AutoConfiguration20B, self).set_site_identification(str(autoconnection_site_id), timeout)

    def set_autoconnection_parameters_to_default(self, *args, **kwargs):
        set_autoconnection_parameters_to_default = self._client.send(
            method='config.autoconnection.restoreDefaults',
            timeout=30,
            parameters={})
        if set_autoconnection_parameters_to_default.status is False:
            error_msg = "Set autoconnection parameters to default failure. Error: {}"
            raise OperationFailure(error_msg.format(set_autoconnection_parameters_to_default.error))
